# Lennard-Jones molecular dynamics, FP32 control (generated by gen_md.py)
# N=27, dt=0.005, steps=200, log every 5 steps. Log at 'log': KE, PE, E, 81 positions.
# FP registers: f20 0.5, f21 1.0, f22 24, f23 48, f24 4, f25 dt, f26 dt/2,
#   f0-f2 xi, f12-f14 Fi, f15 PE, others temporaries. Final E in f10.
.data
dt:      .float 0.005
nsteps:  .word 200
logint:  .word 5
pos:     .float 1.0042, 1.0345, 1.00755
         .float 1.00955, 1.00875, 2.1483
         .float 1.0189, 1.04275, 3.19015
         .float 1.01495, 2.07235, 0.95775
         .float 0.9989, 2.15145, 2.10975
         .float 0.961, 2.08595, 3.2162
         .float 1.00945, 3.20965, 0.9518
         .float 1.0345, 3.271, 2.1041
         .float 0.98275, 3.23505, 3.26665
         .float 2.14925, 0.9822, 1.03405
         .float 2.1427, 1.02455, 2.12615
         .float 2.07135, 1.0302, 3.2806
         .float 2.08945, 2.12665, 1.0487
         .float 2.16025, 2.1081, 2.13405
         .float 2.12335, 2.10465, 3.2876
         .float 2.089, 3.2778, 1.03415
         .float 2.0757, 3.26015, 2.14785
         .float 2.09295, 3.26355, 3.26185
         .float 3.1906, 0.9834, 1.01955
         .float 3.27875, 0.97855, 2.09825
         .float 3.24405, 0.98795, 3.25575
         .float 3.19835, 2.09655, 1.0073
         .float 3.22015, 2.1659, 2.14955
         .float 3.20785, 2.15195, 3.21645
         .float 3.21555, 3.2848, 1.01365
         .float 3.22115, 3.23125, 2.13425
         .float 3.1976, 3.2052, 3.25095
vel:     .float 0.30935633, 0.34487042, 0.169662
         .float -0.09036689, -0.5155025, -0.10422245
         .float -0.5242545, 0.23098916, 0.43443593
         .float 0.4124189, -0.23022996, -0.3257215
         .float -0.5891668, -0.39478838, -0.10706948
         .float -0.2270244, -0.31108564, 0.46518388
         .float 0.2968294, 0.4775421, -0.092834316
         .float 0.029777842, 0.36252204, 0.21806154
         .float -0.31186596, 0.072694205, 0.040976167
         .float 0.2951212, 0.36650786, -0.21867311
         .float 0.34409013, -0.1983432, -0.56771916
         .float 0.38508737, -0.506392, -0.22265896
         .float 0.30252346, 0.28565216, 0.027879821
         .float -0.37393123, 0.03226636, 0.08368164
         .float -0.33805865, 0.14102297, 0.22261678
         .float -0.13534999, 0.25604305, -0.095111944
         .float -0.05961895, 0.41262978, -0.22949183
         .float -0.11485136, 0.14899465, -0.19418864
         .float -0.35571024, -0.5075308, 0.010797631
         .float 0.11404998, -0.025813086, 0.08994511
         .float 0.17896229, 0.56295305, 0.3404839
         .float 0.41925177, -0.05029756, 0.12638712
         .float -0.15641803, -0.20631489, -0.18052289
         .float -0.45478693, -0.2336464, 0.29891723
         .float 0.5052321, -0.50012857, -0.38664797
         .float -0.16040386, -0.28090712, -0.33881783
         .float 0.29910704, 0.26629236, 0.53465146
frc:     .zero 324
log:     .zero 13776                # 41 samples x 84 words
.text
    la s0, pos
    la s1, vel
    la s2, frc
    la s3, log
    li s4, 27                  # N
    li s8, 81                  # 3N
    li t0, 0x3F000000
    fmv.w.x f20, t0            # 0.5
    li t0, 0x3F800000
    fmv.w.x f21, t0            # 1.0
    li t0, 0x41C00000
    fmv.w.x f22, t0            # 24.0
    li t0, 0x42400000
    fmv.w.x f23, t0            # 48.0
    li t0, 0x40800000
    fmv.w.x f24, t0            # 4.0
    fmv.w.x f31, zero          # 0.0
    la t0, dt
    flw f25, 0(t0)             # dt
    fmul.s f26, f20, f25       # h = 0.5*dt
    la t0, nsteps
    lw s6, 0(t0)               # steps
    la t0, logint
    lw s9, 0(t0)               # log interval
    mv s7, s9
    li s5, 1                   # PE needed for sample 0
    jal ra, force
    jal ra, logsample
    beqz s6, done
step_loop:
    jal ra, kick               # v += h*F
    jal ra, drift              # x += dt*v
    addi s7, s7, -1
    seqz s5, s7                # log step?
    jal ra, force
    jal ra, kick
    beqz s5, no_log
    jal ra, logsample
    mv s7, s9
no_log:
    addi s6, s6, -1
    bnez s6, step_loop
done:
    fsgnj.s f10, f16, f16      # final E
    li a0, 0
    li a7, 10                  # exit
    ecall

# ---- force: F = sum of pair forces; PE accumulated when s5 != 0 ----
force:
    mv t0, s2
    mv t1, s8
fz_loop:
    fsw f31, 0(t0)             # F = 0
    addi t0, t0, 4
    addi t1, t1, -1
    bnez t1, fz_loop
    fsgnj.s f15, f31, f31      # PE = 0
    li t1, 0                   # i
    mv t3, s0                  # &pos[i]
    mv a2, s2                  # &frc[i]
fi_loop:
    flw f0, 0(t3)
    flw f1, 4(t3)
    flw f2, 8(t3)
    fsgnj.s f12, f31, f31      # Fi = 0
    fsgnj.s f13, f31, f31
    fsgnj.s f14, f31, f31
    addi t2, t1, 1             # j = i + 1
    addi t4, t3, 12            # &pos[j]
    addi a3, a2, 12            # &frc[j]
    bge t2, s4, fi_store
fj_loop:
    flw f3, 0(t4)
    flw f4, 4(t4)
    flw f5, 8(t4)
    fsub.s f3, f0, f3          # dx
    fsub.s f4, f1, f4          # dy
    fsub.s f5, f2, f5          # dz
    fmul.s f6, f3, f3
    fmul.s f7, f4, f4
    fadd.s f6, f6, f7
    fmul.s f7, f5, f5
    fadd.s f6, f6, f7          # r2
    fdiv.s f7, f21, f6         # inv2 = 1/r2
    fmul.s f8, f7, f7
    fmul.s f8, f8, f7          # s6
    fmul.s f9, f8, f8          # s12
    fmul.s f10, f23, f9        # 48*s12
    fmul.s f11, f22, f8        # 24*s6
    fsub.s f10, f10, f11
    fmul.s f10, f10, f7        # f = (48*s12 - 24*s6)*inv2
    fmul.s f3, f10, f3         # fx
    fmul.s f4, f10, f4         # fy
    fmul.s f5, f10, f5         # fz
    fadd.s f12, f12, f3        # Fi += f*d
    fadd.s f13, f13, f4
    fadd.s f14, f14, f5
    flw f6, 0(a3)              # Fj -= f*d
    fsub.s f6, f6, f3
    fsw f6, 0(a3)
    flw f6, 4(a3)
    fsub.s f6, f6, f4
    fsw f6, 4(a3)
    flw f6, 8(a3)
    fsub.s f6, f6, f5
    fsw f6, 8(a3)
    beqz s5, fj_next
    fsub.s f9, f9, f8          # s12 - s6
    fmul.s f9, f24, f9         # 4*(s12 - s6)
    fadd.s f15, f15, f9        # PE +=
fj_next:
    addi t2, t2, 1
    addi t4, t4, 12
    addi a3, a3, 12
    blt t2, s4, fj_loop
fi_store:
    flw f6, 0(a2)              # F[i] += Fi
    fadd.s f6, f6, f12
    fsw f6, 0(a2)
    flw f6, 4(a2)
    fadd.s f6, f6, f13
    fsw f6, 4(a2)
    flw f6, 8(a2)
    fadd.s f6, f6, f14
    fsw f6, 8(a2)
    addi t1, t1, 1
    addi t3, t3, 12
    addi a2, a2, 12
    blt t1, s4, fi_loop
    ret

# ---- kick: v += h*F (all 3N components) ----
kick:
    mv t0, s1
    mv t1, s2
    mv t2, s8
kick_loop:
    flw f0, 0(t0)
    flw f1, 0(t1)
    fmul.s f1, f26, f1
    fadd.s f0, f0, f1
    fsw f0, 0(t0)
    addi t0, t0, 4
    addi t1, t1, 4
    addi t2, t2, -1
    bnez t2, kick_loop
    ret

# ---- drift: x += dt*v ----
drift:
    mv t0, s0
    mv t1, s1
    mv t2, s8
drift_loop:
    flw f0, 0(t0)
    flw f1, 0(t1)
    fmul.s f1, f25, f1
    fadd.s f0, f0, f1
    fsw f0, 0(t0)
    addi t0, t0, 4
    addi t1, t1, 4
    addi t2, t2, -1
    bnez t2, drift_loop
    ret

# ---- logsample: KE = 0.5*sum(v*v); store KE, PE, E and the positions ----
logsample:
    fsgnj.s f0, f31, f31       # sum = 0
    mv t0, s1
    mv t2, s8
ke_loop:
    flw f1, 0(t0)
    fmul.s f1, f1, f1
    fadd.s f0, f0, f1
    addi t0, t0, 4
    addi t2, t2, -1
    bnez t2, ke_loop
    fmul.s f0, f20, f0         # KE
    fadd.s f16, f0, f15        # E = KE + PE
    fsw f0, 0(s3)
    fsw f15, 4(s3)
    fsw f16, 8(s3)
    mv t0, s0
    addi t1, s3, 12
    mv t2, s8
copy_loop:
    lw t3, 0(t0)
    sw t3, 0(t1)
    addi t0, t0, 4
    addi t1, t1, 4
    addi t2, t2, -1
    bnez t2, copy_loop
    addi s3, s3, 336             # next record
    ret
